/bin/bash -c "python3 - <<'PY'
from fractions import Fraction as F

def eta(a,b):
 if b<a: return 1-b/a
 if b>a: return (b-a)/(1-a)
 return 0.0

def urow(p,q,v,w):
 return min(w*eta(p,q),v*eta(q,p))

def metrics(x1,x2):
 z1=9*x1
 z2=(7*x2/3)-(1/6)
 u=urow(x1,x2,.3,7/15)+urow(z1,z2,1/30,.2)
 e=.3*x1+(7/15)*x2+(1/30)*z1+.2*z2
 return u,e
betas=[0,.5,.75,18/23,.8,.9,1]
mins={b:(1,None) for b in betas}
n=400
for i in range(n+1):
 x1=(1/9)*i/n
 for j in range(n+1):
  x2=(1/14)+(3/7)*j/n
  u,e=metrics(x1,x2)
  for b in betas:
   v=b*u+(1-b)*e
   if v<mins[b][0]: mins[b]=(v,(x1,x2,u,e))
print('Two groups: w=(1/3,2/3), true-positive rates=(.1,.3), predicted-positive rates=(.1,.35)')
for b in betas: print('beta',b,'grid',mins[b])
print('Minimum-error endpoint A',metrics(0,1/14))
print('Equal-FPR endpoint B',metrics(1/14,1/14))
print('Intermediate feasible point at error .05',metrics(1/36,1/14))
print('Lemma 4 check: a=c=0,b=1,d=.5,beta=.5,x=.5; bound D=0, actual derivative abs=.25')
PY"
